const recordPhotoFaceScan = `-- name: RecordPhotoFaceScan :exec
INSERT INTO photo_face_scans (item_id, library_id, faces, status, scanned_at)
VALUES ($1, $2, $3, $4, NOW())
ON CONFLICT (item_id) DO UPDATE SET
    faces      = EXCLUDED.faces,
    status     = EXCLUDED.status,
    scanned_at = NOW()
`

type RecordPhotoFaceScanParams struct {
	ItemID    uuid.UUID `json:"item_id"`
	LibraryID uuid.UUID `json:"library_id"`
	Faces     int32     `json:"faces"`
	Status    string    `json:"status"`
}

func (q *Queries) RecordPhotoFaceScan(ctx context.Context, arg RecordPhotoFaceScanParams) error {
	_, err := q.db.Exec(ctx, recordPhotoFaceScan,
		arg.ItemID,
		arg.LibraryID,
		arg.Faces,
		arg.Status,
	)
	return err
}

const renamePhotoPerson = `-- name: RenamePhotoPerson :one
UPDATE photo_people SET name = $2, updated_at = NOW()
WHERE id = $1
RETURNING id, library_id, name, created_by, created_at, updated_at
`

type RenamePhotoPersonParams struct {
	ID   uuid.UUID `json:"id"`
	Name string    `json:"name"`
}

func (q *Queries) RenamePhotoPerson(ctx context.Context, arg RenamePhotoPersonParams) (PhotoPerson, error) {
	row := q.db.QueryRow(ctx, renamePhotoPerson, arg.ID, arg.Name)
	var i PhotoPerson
	err := row.Scan(
		&i.ID,
		&i.LibraryID,
		&i.Name,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

