const upsertLibraryPhotoSettings = `-- name: UpsertLibraryPhotoSettings :one
INSERT INTO library_photo_settings (library_id, raw_jpeg_pairing, updated_at)
VALUES ($1, $2, NOW())
ON CONFLICT (library_id) DO UPDATE SET
    raw_jpeg_pairing = EXCLUDED.raw_jpeg_pairing,
    updated_at       = NOW()
RETURNING library_id, raw_jpeg_pairing, updated_at
`

type UpsertLibraryPhotoSettingsParams struct {
	LibraryID      uuid.UUID `json:"library_id"`
	RawJpegPairing bool      `json:"raw_jpeg_pairing"`
}

func (q *Queries) UpsertLibraryPhotoSettings(ctx context.Context, arg UpsertLibraryPhotoSettingsParams) (LibraryPhotoSetting, error) {
	row := q.db.QueryRow(ctx, upsertLibraryPhotoSettings, arg.LibraryID, arg.RawJpegPairing)
	var i LibraryPhotoSetting
	err := row.Scan(&i.LibraryID, &i.RawJpegPairing, &i.UpdatedAt)
	return i, err
}
